static class PredictiveModelChecks
{
    static int _checks;
    static void Check(bool okay, string message) { if (!okay) throw new Exception(message); Interlocked.Increment(ref _checks); }
    static void Reject(Action action, string message) { try { action(); } catch (Exception e) when (e is ArgumentException or InvalidOperationException) { Interlocked.Increment(ref _checks); return; } throw new Exception(message); }
    static string Json(object value) => JsonSerializer.Serialize(value, DdiSecurityManager.JsonOptions);
    static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    static T Field<T>(object value, string name) => (T)value.GetType().GetField(name, BindingFlags.Instance | BindingFlags.NonPublic).GetValue(value);
    static readonly List<object> PortPreflightReceipts = [];
    sealed class PausedPredictiveBody : HttpContent
    {
        readonly byte[] _prefix, _suffix;
        readonly TaskCompletionSource _release = new(TaskCreationOptions.RunContinuationsAsynchronously);
        public PausedPredictiveBody(string prefix, string suffix)
        { _prefix = Encoding.UTF8.GetBytes(prefix); _suffix = Encoding.UTF8.GetBytes(suffix); Headers.ContentType = new("application/x-www-form-urlencoded"); }
        public void Resume() => _release.TrySetResult();
        protected override bool TryComputeLength(out long length) { length = _prefix.Length + _suffix.Length; return true; }
        protected override async Task SerializeToStreamAsync(Stream stream, TransportContext context)
        {
            await stream.WriteAsync(_prefix); await stream.FlushAsync();
            await _release.Task.WaitAsync(TimeSpan.FromSeconds(15));
            await stream.WriteAsync(_suffix);
        }
    }
    static int Port()
    {
        // DNS needs both protocols. A TCP-only ephemeral selection may fall inside
        // a UDP exclusion (the retained failed fixture used UDP-excluded port54600).
        for (int attempt = 0; attempt < 64; attempt++)
        {
            using var tcp = new TcpListener(IPAddress.Loopback, 0); tcp.Start();
            int port = ((IPEndPoint)tcp.LocalEndpoint).Port;
            using var udp = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp) { ExclusiveAddressUse = true };
            try
            {
                udp.Bind(new IPEndPoint(IPAddress.Loopback, port));
                PortPreflightReceipts.Add(new { port, tcpAvailable = true, udpAvailable = true, selected = true });
                return port;
            }
            catch (SocketException ex) when (ex.SocketErrorCode is SocketError.AccessDenied or SocketError.AddressAlreadyInUse)
            { PortPreflightReceipts.Add(new { port, tcpAvailable = true, udpAvailable = false, selected = false, errorCode = ex.ErrorCode }); }
        }
        throw new InvalidOperationException("No dual TCP/UDP fixture port available within64 preflights; native service was not started.");
    }
    static LearningDataset Dataset(DateTime now, string suffix = "one")
    {
        var rows = Enumerable.Range(0, 60).Select(i =>
        {
            bool train = i < 40, suspicious = train ? i >= 20 : i >= 50;
            string group = train ? suspicious ? "train-suspicious" : "train-benign" : suspicious ? "eval-suspicious" : "eval-benign";
            var time = train ? now.AddHours(-6).AddMinutes(i * 4) : now.AddMinutes(-30).AddSeconds((i - 40) * 30);
            return new LearningRow(Hash("observation-" + i), Hash(group), time, train ? "Train" : "Evaluation", suspicious ? "Suspicious" : "Benign", Enumerable.Repeat(suspicious ? .9 : .1, 7).ToArray());
        }).ToArray();
        return new("Owned synthetic fixture " + suffix, "Fixture author permits local testing", "Synthetic owned inputs; no operational traffic", "Deliberately separable fixture; not representative", "Labels generated by fixture code; not empirical truth", "Invented group hashes, no domains or inventory", now, true, PredictiveModelRegistry.Schema, rows) { FeatureSourceSha256 = Hash("fixture-suffix") };
    }
