        File.WriteAllText(Path.Combine(root, "RESULT.json"), Json(new { checks = _checks, scope = "Independent non-network store/metric mechanics only; no native process/DNS claim; prior socket bind rejection not retried", fixture = root }));
        Console.WriteLine($"Non-network store/metric checks passed: {_checks}; synthetic mechanics only; fixture: {root}");
