    static void StoreValidationBoundaries(string folder, DateTime now)
    {
        Directory.CreateDirectory(folder);
        var receipts = new List<object>();
        void Invalid(string name, byte[] bytes)
        {
            string owned = Path.Combine(folder, name); Directory.CreateDirectory(owned);
            string path = Path.Combine(owned, "security-advisory-models.json"); File.WriteAllBytes(path, bytes);
            var store = new PredictiveModelRegistry(owned);
            var state = store.Snapshot();
            var advice = store.Evaluate(Enumerable.Repeat(.1, 7).ToArray(), "", now, false, now, Hash("fixture-suffix"));
            Check(state.Models.Length == 0 && state.Selected == "" && state.Status == "Invalid stored registry; deterministic fallback" && advice.Label == "Deterministic heuristic retained", "Invalid stored registry escaped honest fallback: " + name);
            Check(File.ReadAllBytes(path).SequenceEqual(bytes), "Loader overwrote failed registry evidence");
            receipts.Add(new { name, inputSha256 = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(), state.Status, advice.Label });
        }
        byte[] Envelope(string payload, string hash = null) => Encoding.UTF8.GetBytes(Json(new { payload, sha256 = hash ?? Hash(payload) }));
        string emptyPayload = "{\"revision\":0,\"selected\":\"\",\"previous\":\"\",\"models\":[],\"status\":\"Empty\",\"retiredDatasets\":[]}";
        Invalid("bad-payload-hash", Envelope(emptyPayload, new string('0', 64)));
        string correctHash = Hash(emptyPayload);
        Invalid("one-hex-digit-hash-mismatch", Envelope(emptyPayload, (correctHash[0] == '0' ? "1" : "0") + correctHash[1..]));
        Invalid("null-envelope", "null"u8.ToArray());
        Invalid("missing-payload", "{}"u8.ToArray());
        Invalid("null-payload", Encoding.UTF8.GetBytes(Json(new { payload = (string)null, sha256 = new string('0', 64) })));
        Invalid("null-state", Envelope("null"));
        Invalid("malformed-payload", Envelope("{corrupt"));
        Invalid("oversize-envelope", Enumerable.Repeat((byte)' ', 4 * 1024 * 1024 + 1).ToArray());
        string validRoot = Path.Combine(folder, "valid"); Directory.CreateDirectory(validRoot);
        var valid = new PredictiveModelRegistry(validRoot);
        var dataset = Dataset(now, "store-validation");
        File.WriteAllText(Path.Combine(validRoot, "synthetic-dataset.json"), Json(dataset));
        var trained = valid.Train(Json(dataset), 0, "store-fixture", now);
        valid.Select(trained.Models[0].Id, 1, "store-fixture", now);
        string validPayload = JsonNode.Parse(File.ReadAllText(Path.Combine(validRoot, "security-advisory-models.json")))["payload"].GetValue<string>();
        void Mutation(string name, Action<JsonNode> mutate)
        {
            var payload = JsonNode.Parse(validPayload); mutate(payload);
            Invalid(name, Envelope(payload.ToJsonString(DdiSecurityManager.JsonOptions)));
        }
        Mutation("null-model-list", p => p["models"] = null);
        Mutation("null-model", p => p["models"][0] = null);
        Mutation("null-selected", p => p["selected"] = null);
        Mutation("unsupported-feature-schema", p => p["models"][0]["featureSchema"] = "unsupported");
        Mutation("bad-model-hash", p => p["models"][0]["artifactSha256"] = new string('0', 64));
        Mutation("invalid-dimensions", p => p["models"][0]["benignMean"] = new JsonArray(.1));
        Mutation("unrepresentable-number", p => p["models"][0]["benignMean"][0] = JsonNode.Parse("1e999"));
        Mutation("null-dataset", p => p["models"][0]["dataset"] = null);
        Mutation("null-baseline", p => p["models"][0]["baselines"][0] = null);
        Mutation("maximum-created-time", p => p["models"][0]["createdAt"] = "9999-12-31T23:59:59.9999999Z");
        Mutation("unsupported-evaluation", p => p["models"][0]["evaluation"]["protocol"] = "unsupported");
        Mutation("missing-selected-model", p => p["selected"] = new string('f', 64));
        Mutation("duplicate-model-id", p => p["models"].AsArray().Add(p["models"][0].DeepClone()));
        var reload = new PredictiveModelRegistry(validRoot);
        Check(reload.Snapshot().Selected == trained.Models[0].Id && reload.Evaluate(Enumerable.Repeat(.1, 7).ToArray(), "", now, false, now, dataset.FeatureSourceSha256).Label == "Benign" && reload.Evaluate(Enumerable.Repeat(.9, 7).ToArray(), "", now, false, now, dataset.FeatureSourceSha256).Label == "Suspicious", "Valid stored selection/inference regressed");
        bool programmerErrorPropagated = false;
        try { _ = new PredictiveModelRegistry(null); } catch (ArgumentNullException) { programmerErrorPropagated = true; }
        Check(programmerErrorPropagated, "Unexpected caller error was suppressed");
        File.WriteAllText(Path.Combine(folder, "store-validation-receipts.json"), Json(receipts));
    }
    static void AuditorMetricBoundary(string path, string folder)
    {
        byte[] bytes = File.ReadAllBytes(path);
        const string expected = "ee7ec8fe099c9cee717525d728ebc860e67c4b48dfd772a8799a17c4f3bb0f6c";
        Check(Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant() == expected, "Auditor dataset is not the exact supervisor-qualified synthetic input");
        var d = JsonSerializer.Deserialize<LearningDataset>(bytes, DdiSecurityManager.JsonOptions);
        Check(d.Synthetic && d.Rows.Length == 60, "Auditor input lost synthetic provenance");
        Directory.CreateDirectory(folder);
        File.WriteAllBytes(Path.Combine(folder, "synthetic-dataset.json"), bytes);
        // Explicit frozen logical as-of reproduces original mechanical boundary. It is not
        // a claim that old observations are fresh at an arbitrary later wall-clock time.
        DateTime asOf = d.CollectedAt;
        var registry = new PredictiveModelRegistry(folder);
        var state = registry.Train(Encoding.UTF8.GetString(bytes), 0, "qualified-auditor-fixture", asOf);
        var model = state.Models.Single();
        registry.Select(model.Id, state.Revision, "qualified-auditor-fixture", asOf);
        var served = d.Rows.Where(r => r.Partition == "Evaluation").Select(r => registry.Evaluate(r.Features, r.DeviceGroupSha256, r.ObservedAt, r.SampleLimited, asOf, d.FeatureSourceSha256)).ToArray();
        Check(served.Length == 20 && served.All(a => a.Label == "Deterministic heuristic retained" && a.Status == "Outside training support or ambiguous class; deterministic fallback"), "Exact auditor input no longer reproduces support abstention");
        Check(model.Evaluation is { Classified: 0, Abstained: 20, Coverage: 0, Precision: null, RecallAmongClassified: null, KnownSuspiciousDetectionFraction: 0 }, "Exact auditor input still reports unsupported learned classifications");
        File.WriteAllText(Path.Combine(folder, "metric-receipt.json"), Json(new { datasetSha256 = expected, asOf, asOfBasis = "Frozen synthetic collection time, not present wall-clock freshness", model.Id, model.ArtifactSha256, model.FeatureDefinitionSha256, model.Evaluation, served, claim = "Synthetic mechanical PRED-METRIC-001 regression only" }));
    }
    static void MetricBoundaries(string folder, DateTime now)
    {
        Directory.CreateDirectory(folder);
        var receipts = new List<object>();
        foreach (string scenario in new[] { "all-abstain", "mixed", "supported", "mixed-errors", "stale", "sample-limited" })
        {
            string owned = Path.Combine(folder, scenario); Directory.CreateDirectory(owned);
            var original = Dataset(now, scenario);
            var rows = original.Rows.Select((r, i) =>
            {
                bool positive = r.Label == "Suspicious";
                double value = positive ? 1 : 0;
                if (i >= 40 && (scenario == "all-abstain" || ((scenario == "mixed" || scenario == "mixed-errors") && i % 10 >= 5))) value = positive ? .51 : .49;
                else if (i >= 40 && scenario == "mixed-errors") value = positive ? 0 : 1;
                return r with { Features = Enumerable.Repeat(value, 7).ToArray(), ObservedAt = i >= 40 && scenario == "stale" ? now.AddHours(-2).AddSeconds(i) : r.ObservedAt, SampleLimited = i >= 40 && scenario == "sample-limited" };
            }).ToArray();
            var dataset = original with { Rows = rows };
            File.WriteAllText(Path.Combine(owned, "synthetic-dataset.json"), Json(dataset));
            var registry = new PredictiveModelRegistry(owned);
            var state = registry.Train(Json(dataset), 0, "metric-fixture", now);
            var m = state.Models.Single();
            registry.Select(m.Id, state.Revision, "metric-fixture", now);
            Check(m.BenignMean.All(v => v == 0) && m.SuspiciousMean.All(v => v == 1), "Held-out records contaminated trained centroids");
            int tp = 0, tn = 0, fp = 0, fn = 0, abstained = 0;
            Dictionary<string, int> reasons = new();
            foreach (var r in rows.Where(r => r.Partition == "Evaluation"))
            {
                var served = registry.Evaluate(r.Features, r.DeviceGroupSha256, r.ObservedAt, r.SampleLimited, now, dataset.FeatureSourceSha256);
                Check(served.Mode == "Monitor", "Boundary advice gained authority");
                if (served.Label == "Deterministic heuristic retained") { abstained++; reasons[served.Status] = reasons.GetValueOrDefault(served.Status) + 1; continue; }
                if (r.Label == "Suspicious") { if (served.Label == "Suspicious") tp++; else fn++; } else { if (served.Label == "Suspicious") fp++; else tn++; }
            }
            var e = m.Evaluation;
            Check(e.TruePositive == tp && e.TrueNegative == tn && e.FalsePositive == fp && e.FalseNegative == fn && e.Abstained == abstained && e.TotalRows == 20 && e.EligibleRows == 20 && e.Classified + e.Abstained == 20 && e.UnknownLabels == 0, "Held-out results differ from served decisions or denominators");
            Check(e.AbstentionReasons.All(r => reasons.GetValueOrDefault(r.Reason) == r.Rows) && reasons.Count == e.AbstentionReasons.Length, "Held-out abstention reasons differ from serving");
            if (scenario is "all-abstain" or "stale" or "sample-limited") Check(e is { Classified: 0, Abstained: 20, Coverage: 0, Precision: null, RecallAmongClassified: null, KnownSuspiciousDetectionFraction: 0 }, "All-abstain result claims perfect/defined precision or loses cohort denominator");
            if (scenario == "mixed") Check(e is { TruePositive: 5, TrueNegative: 5, Abstained: 10, Coverage: .5, Precision: 1, RecallAmongClassified: 1, KnownSuspiciousDetectionFraction: .5 }, "Mixed coverage arithmetic failed");
            if (scenario == "supported") Check(e is { TruePositive: 10, TrueNegative: 10, Abstained: 0, Coverage: 1 }, "Supported positive/negative path failed");
            if (scenario == "mixed-errors") Check(e is { FalsePositive: 5, FalseNegative: 5, Abstained: 10, Coverage: .5, Precision: 0, RecallAmongClassified: 0 }, "Wrong classifications or abstentions were counted as correct");
            var reload = new PredictiveModelRegistry(owned);
            Check(Json(reload.Snapshot().Models.Single().Evaluation) == Json(e), "Reload changed served metric protocol");
            receipts.Add(new { scenario, m.Id, m.ArtifactSha256, evaluation = e, served = new { tp, tn, fp, fn, abstained, reasons } });
        }
        var invalid = Dataset(now);
        var unknown = invalid.Rows.ToArray(); unknown[40] = unknown[40] with { Label = "Unknown" };
        var rejectRegistry = new PredictiveModelRegistry(folder);
        Reject(() => rejectRegistry.Train(Json(invalid with { Rows = unknown }), 0, "metric-fixture", now), "Unknown label became a benign denominator");
        var sampled = invalid.Rows.ToArray(); sampled[0] = sampled[0] with { SampleLimited = true };
        Reject(() => rejectRegistry.Train(Json(invalid with { Rows = sampled }), 0, "metric-fixture", now), "Sample-limited training row fitted model");
        File.WriteAllText(Path.Combine(folder, "metric-boundaries.json"), Json(receipts));
    }
    static async Task Native(string folder)
