                    foreach (string operation in new[] { "list", "context", "train", "select", "retire" }) Check((await Call(fresh, "/api/security/predictive/" + operation)).GetProperty("status").GetString() == "invalid-token", "Anonymous model API accepted");
                    await Login(original);
