                    var reader = auth.CreateUser("Predictive owned reader", "predictive-reader", readerPassword);
                    auth.SetPermission(PermissionSection.Settings, reader, PermissionFlag.View);
                    var modifier = auth.CreateUser("Predictive owned settings modifier", "predictive-modifier", readerPassword);
                    auth.SetPermission(PermissionSection.Settings, modifier, PermissionFlag.ViewModify);
