                    foreach (string operation in new[] { "train", "select", "retire" })
                    foreach (string transition in new[] { "logout", "expire", "revoke-rights" })
                    {
                        string name = "predictive-pending-" + operation + "-" + transition;
                        var actor = auth.CreateUser("Owned pending predictive fixture", name, readerPassword);
                        auth.SetPermission(PermissionSection.Settings, actor, PermissionFlag.ViewModify);
                        auth.SetPermission(PermissionSection.Administration, actor, PermissionFlag.Modify);
                        using var caller = new HttpClient { BaseAddress = original.BaseAddress };
                        await Login(caller, name, readerPassword);
                        string actorToken = caller.DefaultRequestHeaders.Authorization.Parameter;
                        Check(auth.GetSession(actorToken).LastSeenRemoteAddress.Equals(IPAddress.Loopback), "Pending actor fresh target source differs");
                        Check((await Call(caller, "/api/security/predictive/select", ("modelId", id), ("revision", nativeRevision.ToString()))).GetProperty("status").GetString() == "ok", "Fresh owned actor cannot exercise required model modify privilege");
                        nativeRevision++;
                        if (transition == "expire") actor.SessionTimeoutSeconds = 60;
                        string storeFile = Path.Combine(folder, "security-advisory-models.json"); byte[] before = File.ReadAllBytes(storeFile);
                        string marker = "Predictive-owned-paused-" + operation + "-" + transition;
