                        request.Headers.UserAgent.ParseAdd(marker);
                        using var body = new PausedPredictiveBody("revision=" + nativeRevision + "&" + (operation == "train" ? "dataset=" : "modelId="), Uri.EscapeDataString(operation == "train" ? Json(Dataset(DateTime.UtcNow, name)) : id));
