            Check(persisted.GetProperty("response").GetProperty("registry").GetProperty("models").GetArrayLength() == 1 && persisted.GetProperty("response").GetProperty("registry").GetProperty("revision").GetInt64() == nativeRevision, "Full-process restart lost model/baseline history");
            await Answer();
            await child.StandardInput.WriteLineAsync("stop"); await child.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(20));
            File.WriteAllText(Path.Combine(folder, "child-output.log"), await output + await error);
