            string coldReady = Path.Combine(folder, "cold-invalid-ready.json");
            using (var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(20))) while (!File.Exists(coldReady) && !cold.HasExited) await Task.Delay(25, timeout.Token);
            Check(File.Exists(coldReady), "Cold invalid-registry process not ready");
            using (var identity = JsonDocument.Parse(File.ReadAllText(coldReady))) Check(identity.RootElement.GetProperty("pid").GetInt32() == cold.Id && cold.Id != child.Id && identity.RootElement.GetProperty("registryStatus").GetString() == "Invalid stored registry; deterministic fallback", "Cold process identity/fallback invalid");
            using var coldClient = new HttpClient { BaseAddress = original.BaseAddress };
            await Login(coldClient);
            var coldList = await Call(coldClient, "/api/security/predictive/list");
            Check(coldList.GetProperty("status").GetString() == "ok" && coldList.GetProperty("response").GetProperty("registry").GetProperty("models").GetArrayLength() == 0, "Cold invalid-registry management did not fall back");
            await Answer();
            await cold.StandardInput.WriteLineAsync("stop"); await cold.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(20));
            File.WriteAllText(Path.Combine(folder, "cold-invalid-output.log"), await coldOutput + await coldError);
            Check(cold.ExitCode == 0, "Cold invalid-registry process failed");
            File.WriteAllText(Path.Combine(folder, "native-receipt.json"), Json(new { pid = Environment.ProcessId, startedUtc = Process.GetCurrentProcess().StartTime.ToUniversalTime(), httpPort, dnsPort, elapsedMilliseconds = elapsed.Elapsed.TotalMilliseconds, scope = "Finite synthetic authoritative UDP NoError+AA+192.0.2.42 samples before/concurrent management/after failure and distinct-process restart; no continuous availability, throughput, recursive, DHCP or remote-source qualification", currentRights = "Fresh loopback admin read/write/target-seen source and original retained; owned read-only/missing modify roles; nine actual paused-body train/select/retire logout/expiry/revoked Admin Modify cases with unchanged durable state; valid current paused select control; pending list/context logout with data withheld. Expiry uses explicit owned target LastSeen seam and actual HasExpired, not wall-clock timeout. Remote paths and cluster proxy/token matrix untested." }));
        }
        finally { foreach (var p in old) Environment.SetEnvironmentVariable(p.Key, p.Value); }
    }
    public static async Task Child(string folder, bool invalidRegistry = false)
    {
        await using var service = new DnsWebService(true, folder);
        await service.StartAsync(true);
        var core = typeof(DnsWebService).Assembly.Location;
        var registry = Field<DdiSecurityManager>(service, "_security").PredictiveModels;
        if (invalidRegistry) Check(registry.Snapshot().Models.Length == 0 && registry.Evaluate(Enumerable.Repeat(.1, 7).ToArray(), "", DateTime.UtcNow, false, DateTime.UtcNow).Label == "Deterministic heuristic retained", "Cold model fallback failed");
        File.WriteAllText(Path.Combine(folder, invalidRegistry ? "cold-invalid-ready.json" : "child-ready.json"), Json(new { pid = Environment.ProcessId, startedUtc = Process.GetCurrentProcess().StartTime.ToUniversalTime(), core, coreSha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(core))).ToLowerInvariant(), featureSchema = PredictiveModelRegistry.Schema, featureDefinitionSha256 = PredictiveModelRegistry.FeatureDefinitionSha256, framework = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription, runtime = Environment.Version.ToString(), loadedAssemblies = AppDomain.CurrentDomain.GetAssemblies().Where(a => !a.IsDynamic && !string.IsNullOrEmpty(a.Location)).OrderBy(a => a.FullName, StringComparer.Ordinal).Select(a => new { identity = a.FullName, path = a.Location, sha256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(a.Location))).ToLowerInvariant() }).ToArray(), registryStatus = registry.Snapshot().Status, models = registry.Snapshot().Models.Select(m => new { m.Id, m.ArtifactSha256, m.FeatureDefinitionSha256 }).ToArray() }));
        if (await Console.In.ReadLineAsync() != "stop") throw new Exception("Unexpected fixture stop command");
    }
